import{_ as t,o as i,c as h,a2 as o}from"./chunks/framework.mRCPFc5l.js";const l=JSON.parse('{"title":"Tiếng Anh","description":"","frontmatter":{},"headers":[],"relativePath":"ideas/inquiry-ib/tieng-anh.md","filePath":"ideas/inquiry-ib/tieng-anh.md"}'),c={name:"ideas/inquiry-ib/tieng-anh.md"};function e(g,n,a,r,s,u){return i(),h("div",null,[...n[0]||(n[0]=[o('<h1 id="tieng-anh" tabindex="-1">Tiếng Anh <a class="header-anchor" href="#tieng-anh" aria-label="Permalink to &quot;Tiếng Anh&quot;">​</a></h1><p>Trên trang này# Tiếng Anh — ba bài học inquiry theo IB <a href="#tieng-anh-—-ba-bai-hoc-inquiry-theo-ib">​</a> Trong IB, môn này là <strong>Language Acquisition</strong>, và nguyên tắc gốc của nó khác hẳn cách dạy ngữ pháp quen thuộc: học sinh <strong>gặp ngôn ngữ trong ngữ cảnh trước, rút ra quy tắc sau</strong>. Quy tắc không được đọc cho chép. Nó được học sinh phát hiện — và vì thế nó bám lại. Ý xuyên suốt cả mônNgữ pháp không phải luật tuỳ tiện phải thuộc. Mỗi cấu trúc tồn tại để diễn đạt một quan hệ mà cấu trúc khác không diễn đạt được. Cũng quan trọng — nhưng không phải ý lớn nhất- Người nghe và mục đích quyết định cách nói, không chỉ nội dung cần truyền đạt.</p><ul><li>Một câu đúng ngữ pháp vẫn có thể sai hoàn toàn về ngữ vực — và sai ngữ vực thường tốn kém hơn sai ngữ pháp.</li><li>Người viết định hướng người đọc bằng cả những gì họ chọn không nói ra.</li></ul><h2 id="demo-1-—-present-perfect-quy-tac-do-hoc-sinh-tu-tim-ra-​" tabindex="-1">Demo 1 — Present Perfect: quy tắc do học sinh tự tìm ra <a href="#demo-1-—-present-perfect-quy-tac-do-hoc-sinh-tu-tim-ra">​</a> <a class="header-anchor" href="#demo-1-—-present-perfect-quy-tac-do-hoc-sinh-tu-tim-ra-​" aria-label="Permalink to &quot;Demo 1 — Present Perfect: quy tắc do học sinh tự tìm ra [​](#demo-1-—-present-perfect-quy-tac-do-hoc-sinh-tu-tim-ra)&quot;">​</a></h2><p><strong>Lớp</strong>8–10<strong>Key concept</strong>Communication<strong>Related concepts</strong>Structure · Meaning · Context<strong>Global context</strong>Identities and relationships<strong>Statement of inquiry</strong>Cấu trúc ngữ pháp không tuỳ tiện — mỗi cấu trúc tồn tại để diễn đạt một quan hệ cụ thể với thời gian.<strong>Cần biết trước</strong>Thì quá khứ đơn, hiện tại đơn</p><h3 id="vi-sao-thi-nay-kho-​" tabindex="-1">Vì sao thì này khó <a href="#vi-sao-thi-nay-kho">​</a> <a class="header-anchor" href="#vi-sao-thi-nay-kho-​" aria-label="Permalink to &quot;Vì sao thì này khó [​](#vi-sao-thi-nay-kho)&quot;">​</a></h3><p>Present perfect là chỗ người học tiếng Việt vấp nhiều nhất, vì tiếng Việt không có cấu trúc tương ứng. Dạy bằng quy tắc — <em>&quot;dùng khi hành động bắt đầu trong quá khứ và kéo dài tới hiện tại&quot;</em> — thường không có tác dụng: học sinh thuộc câu đó mà vẫn dùng sai.</p><h3 id="dien-bien-tiet-hoc-​" tabindex="-1">Diễn biến tiết học <a href="#dien-bien-tiet-hoc">​</a> <a class="header-anchor" href="#dien-bien-tiet-hoc-​" aria-label="Permalink to &quot;Diễn biến tiết học [​](#dien-bien-tiet-hoc)&quot;">​</a></h3><p><strong>Bước 1 — Dữ liệu trước, quy tắc sau (12 phút).</strong> Giáo viên đưa 12 câu, không giải thích gì, chỉ chia hai cột: Cột ACột BI <strong>went</strong> to Japan in 2019.I <strong>have been</strong> to Japan.She <strong>finished</strong> the book last night.She <strong>has finished</strong> the book.We <strong>lived</strong> here for five years. *(giờ đã chuyển đi)*We <strong>have lived</strong> here for five years. <em>(vẫn ở)<em>Did you <strong>see</strong> the news this morning?<strong>Have</strong> you <strong>seen</strong> the news?</em>&quot;Đọc kỹ. Cột A khác cột B ở chỗ nào? Đừng nói về hình thức — nói về <strong>nghĩa</strong>.&quot;</em><strong>Bước 2 — Học sinh đề xuất quy tắc (12 phút).</strong> Các nhóm viết quy tắc của mình. Điển hình:</p><ul><li><em>&quot;Cột A có thời gian cụ thể, cột B thì không.&quot;</em></li><li><em>&quot;Cột B là chuyện chưa xong.&quot;</em></li><li><em>&quot;Cột B liên quan tới bây giờ.&quot;</em> Giáo viên ghi tất cả lên bảng, <strong>không sửa</strong>. <strong>Bước 3 — Thử phá quy tắc (12 phút).</strong> Đây là bước quan trọng nhất, và cũng là bước bị bỏ nhiều nhất trong các lớp học &quot;khám phá&quot; làm hời hợt. Giáo viên đưa thêm câu mới và hỏi: <em>&quot;Quy tắc của nhóm em có giải thích được câu này không?&quot;</em><em>I have finished my homework. Now I can play.</em> Quy tắc &quot;chuyện chưa xong&quot; vỡ ngay — bài tập đã xong hẳn. <em>She has lost her keys.</em><em>&quot;Vậy chìa khoá tìm thấy chưa? Câu này cho biết gì về hiện tại?&quot;</em> Học sinh dần tinh chỉnh: present perfect nói về <strong>kết quả còn hiệu lực ở hiện tại</strong>, không phải về việc hành động đã xong hay chưa. <strong>Bước 4 — Chốt bằng ngôn ngữ chính xác (8 phút).</strong> Giáo viên đưa cách diễn đạt chuẩn, và học sinh thấy nó khớp với quy tắc mà chính các em đã tinh chỉnh qua ba vòng. <strong>Bước 5 — Dùng thật (15 phút).</strong> Phỏng vấn cặp đôi: <em>&quot;Find someone who has… travelled abroad · broken a bone · met a famous person.&quot;</em> Học sinh phải dùng cấu trúc để đạt một mục đích giao tiếp thật, không phải để điền vào chỗ trống.</li></ul><h3 id="cham-theo-tieu-chi-​" tabindex="-1">Chấm theo tiêu chí <a href="#cham-theo-tieu-chi">​</a> <a class="header-anchor" href="#cham-theo-tieu-chi-​" aria-label="Permalink to &quot;Chấm theo tiêu chí [​](#cham-theo-tieu-chi)&quot;">​</a></h3><p>Tiêu chíỞ bài này<strong>A — Listening</strong>Nghe bạn kể trải nghiệm, nhận diện cấu trúc<strong>B — Reading</strong>Đọc và phân loại các câu ví dụ<strong>C — Speaking</strong>Phỏng vấn, hỏi và trả lời tự nhiên<strong>D — Writing</strong>Viết đoạn về trải nghiệm bản thân</p><h2 id="demo-2-—-ngu-vuc-cung-mot-noi-dung-nam-cach-noi-​" tabindex="-1">Demo 2 — Ngữ vực: cùng một nội dung, năm cách nói <a href="#demo-2-—-ngu-vuc-cung-mot-noi-dung-nam-cach-noi">​</a> <a class="header-anchor" href="#demo-2-—-ngu-vuc-cung-mot-noi-dung-nam-cach-noi-​" aria-label="Permalink to &quot;Demo 2 — Ngữ vực: cùng một nội dung, năm cách nói [​](#demo-2-—-ngu-vuc-cung-mot-noi-dung-nam-cach-noi)&quot;">​</a></h2><p><strong>Lớp</strong>9–11<strong>Key concept</strong>Communication<strong>Related concepts</strong>Audience · Purpose · Register<strong>Global context</strong>Personal and cultural expression<strong>Statement of inquiry</strong>Người nghe và mục đích quyết định cách nói, không chỉ nội dung cần truyền đạt.<strong>Cần biết trước</strong>Vốn từ ở mức B1 trở lên</p><h3 id="dien-bien-tiet-hoc-​-1" tabindex="-1">Diễn biến tiết học <a href="#dien-bien-tiet-hoc-1">​</a> <a class="header-anchor" href="#dien-bien-tiet-hoc-​-1" aria-label="Permalink to &quot;Diễn biến tiết học [​](#dien-bien-tiet-hoc-1)&quot;">​</a></h3><p><strong>Bước 1 — Một tình huống, năm người nhận (15 phút).</strong><em>&quot;Em bị ốm và không đi học được. Viết tin nhắn cho: bạn thân · giáo viên chủ nhiệm · nhà tuyển dụng chỗ em làm thêm · bà của em · một hệ thống báo vắng tự động.&quot;</em> Học sinh viết cả năm. Không có hướng dẫn nào về &quot;trang trọng&quot; hay &quot;thân mật&quot;. <strong>Bước 2 — So sánh và tự phát hiện (15 phút).</strong> Dán năm bản cạnh nhau. Giáo viên hỏi:</p><ul><li><em>&quot;Bản nào dài nhất? Vì sao?&quot;</em></li><li><em>&quot;Bản nào có lời xin lỗi? Vì sao bản kia không cần?&quot;</em></li><li><em>&quot;Em dùng &#39;sick&#39; ở đâu và &#39;unwell&#39; ở đâu? Vì sao?&quot;</em></li><li><em>&quot;Bản nào dùng viết tắt? Bản nào không?&quot;</em> Học sinh tự xây được một bảng đặc điểm ngữ vực — trước khi nghe từ &quot;register&quot; bao giờ. <strong>Bước 3 — Cố tình dùng sai (10 phút).</strong><em>&quot;Gửi tin nhắn kiểu bạn thân cho nhà tuyển dụng. Đọc to lên.&quot;</em> Cả lớp cười. Rồi câu hỏi: <em>&quot;Vì sao nó buồn cười? Chính xác cái gì sai — ngữ pháp có sai không?&quot;</em> Học sinh nhận ra: ngữ pháp hoàn toàn đúng, nhưng ngữ vực sai — và sai ngữ vực có thể gây hậu quả lớn hơn sai ngữ pháp. <strong>Bước 4 — Ứng dụng vào bài thi thật (10 phút).</strong><em>&quot;Trong bài viết IELTS Task 1 dạng thư, đề nói viết cho ai? Điều đó đổi cách em mở đầu thế nào?&quot;</em> Bài học được nối trực tiếp vào mục tiêu thi cử — inquiry không đối lập với việc ôn thi.</li></ul><h2 id="demo-3-—-đoc-suy-luan-đieu-van-ban-khong-noi-ra-​" tabindex="-1">Demo 3 — Đọc suy luận: điều văn bản không nói ra <a href="#demo-3-—-đoc-suy-luan-đieu-van-ban-khong-noi-ra">​</a> <a class="header-anchor" href="#demo-3-—-đoc-suy-luan-đieu-van-ban-khong-noi-ra-​" aria-label="Permalink to &quot;Demo 3 — Đọc suy luận: điều văn bản không nói ra [​](#demo-3-—-đoc-suy-luan-đieu-van-ban-khong-noi-ra)&quot;">​</a></h2><p><strong>Lớp</strong>9–12<strong>Key concept</strong>Connections<strong>Related concepts</strong>Inference · Bias · Word choice<strong>Global context</strong>Fairness and development<strong>Statement of inquiry</strong>Người viết định hướng người đọc bằng những lựa chọn không được nói ra thành lời.<strong>Cần biết trước</strong>Đọc hiểu ở mức B1–B2</p><h3 id="dien-bien-tiet-hoc-​-2" tabindex="-1">Diễn biến tiết học <a href="#dien-bien-tiet-hoc-2">​</a> <a class="header-anchor" href="#dien-bien-tiet-hoc-​-2" aria-label="Permalink to &quot;Diễn biến tiết học [​](#dien-bien-tiet-hoc-2)&quot;">​</a></h3><p><strong>Bước 1 — Hai bản tin về một sự kiện (12 phút).</strong> Giáo viên đưa hai đoạn tin ngắn về cùng một sự việc, từ hai nguồn có góc nhìn khác nhau — hoặc hai bản do chính giáo viên soạn để làm rõ khác biệt. <em>&quot;Hai bản này có bản nào nói sai sự thật không?&quot;</em> Thường là không. Mọi dữ kiện đều đúng. <strong>Bước 2 — Truy vào từ ngữ (15 phút).</strong><em>&quot;Gạch chân mọi từ mang cảm xúc. So hai bản.&quot;</em> Học sinh phát hiện các cặp: <em>protesters / rioters</em> · <em>claimed / stated</em> · <em>only 200 people / as many as 200 people</em> · <em>admitted / explained</em>. <em>&quot;Cặp nào làm em nghiêng về phía nào? Chính xác thì từ nào làm điều đó?&quot;</em><strong>Bước 3 — Điều bị bỏ đi (12 phút).</strong><em>&quot;Bản A có thông tin nào mà bản B không có? Vì sao bản B bỏ nó đi?&quot;</em> Học sinh nhận ra: <strong>im lặng cũng là một lựa chọn của người viết</strong>, và nó thường mạnh hơn cả những gì được nói ra. <strong>Bước 4 — Tự viết thiên lệch (15 phút).</strong><em>&quot;Viết lại một sự kiện ở trường bằng hai bản: một bản làm người đọc thông cảm với ban giám hiệu, một bản làm người đọc thông cảm với học sinh. Không được viết sai sự thật nào.&quot;</em> Ràng buộc &quot;không được viết sai sự thật&quot; là chỗ toàn bộ bài học nằm ở đó. Học sinh phải đạt hiệu ứng chỉ bằng cách chọn từ, chọn thứ tự, và chọn cái gì để im lặng. <strong>Bước 5 — Tranh luận (10 phút).</strong><em>&quot;Có thể viết một bản tin hoàn toàn không thiên lệch không? Nếu không, người đọc nên làm gì?&quot;</em> Điều lấy được cho gia đình Demo 3 làm được với bất kỳ tin tức nào, bằng tiếng Việt hay tiếng Anh, trong 10 phút: đọc hai bản về cùng một chuyện và hỏi <em>&quot;hai bên dùng từ khác nhau ở chỗ nào?&quot;</em> Đây là kỹ năng có tuổi thọ dài hơn hầu hết những gì học ở trường. <a href="/ideas/inquiry-ib/lich-su-dia-ly">Lịch sử · Địa lý →</a></p>',21)])])}const d=t(c,[["render",e]]);export{l as __pageData,d as default};
